#!/usr/bin/env python3
"""Report the executed unavailable44 experiment without invented payoff."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "docs/representation_regions_20261008"


def main():
    result = json.loads((OUT / "results.json").read_text())
    audit = json.loads((OUT / "independent_availability_audit.json").read_text())
    assert audit["passed"] and not audit["errors"] and audit["all_common_clocks_empty"]
    assert audit["fitted_models_requiring_separate_economic_audit"] == 0
    assert all(x["known_age_rows"] == 0 and x["large_transformed_m5_bars"] == 0 and x["all44_finite_rows"] == 0
        for report in audit["symbols"].values() for x in report.values())
    assert len(result["rows"]) == 72 and all(r["metrics"]["completed"] == 0 for r in result["rows"])
    text = ["# إزالة أثر الانفجارات من المدخلات: تشغيل فعلي ورفض صيغة44", "",
        "**لم يتحقق هدف الربح. هذه الصيغة غير قابلة للتشغيل ضمن المدخلات الـ44 المحددة: صفر فرص مشتركة، صفر نماذج مدرّبة وصفر صفقات. PF والعائد غير معرّفين/NOT TESTED، وليس PF=0.**", "",
        "اختُبرت فرضية أن أثر الانفجارات السابقة في المؤشرات قد يخفي سياقًا مفيدًا. أُعيد بناء مؤشرات H4/H1/M15/M5/M1 من الأسعار الأصلية، ومرة أخرى من سلسلة خصائص حُذف منها فقط التغير الأصلي الكبير المكتشف. كان الهدف إصدار مناطق شراء مسبقة لـBoom وبيع لـCrash، مع مقارنة دخول زمني مباشر. الأسعار المعدّلة للخصائص وحدها؛ الأسعار الأصلية بقيت أساس الدخول والوقف والتكلفة والربح.", "",
        "المصادر نفسها: 722 ملفًا و62,380,130 سعرًا أصليًا، مع إبقاء670 ثانية ناقصة. أربع عمليات إعداد/تدريب مخططة لكل رمز:40/50/60% مع النافذة التالية10%، و70% للجزء30% ثم180 يومًا لاحقة. عُيّرت عتبة اكتشاف الانفجار من بيانات تدريب كل نافذة فقط، ولم تُستخدم عتبة يونيو في التدريب الأقدم. الفترات مكشوفة سابقًا؛ ليست fresh OOS.", "",
        "## التوافر الفعلي في ساعات التدريب", "",
        "كل عدد هو فرص ساعةUTC00/30 بعد الحذف المخطط31 دقيقة. تتداخل فترات التدريب؛ لا تُجمع الأعداد كعينة مستقلة.", "",
        "| الرمز | تدريب أول | فرص أصلية صالحة | فرص محوّلة صالحة | فرص مشتركة | نتائج تدريب مكتملة | الحالة |",
        "|---|---:|---:|---:|---:|---:|---|"]
    for symbol in ("BOOM600", "CRASH600"):
        for fold in ("fit40", "fit50", "fit60", "fit70"):
            f = result["symbols"][symbol]["folds"][fold]
            m = json.loads((ROOT / f["fit"]["path"]).read_text()); c = m["training_clock"]
            assert m["status"] == "NOT_FIT_INSUFFICIENT_COMMON_LABELS"
            text.append(f"| {symbol} | {fold[3:]}% | {c['raw_valid_clock_rows']} | {c['transformed_valid_clock_rows']} | {c['common_clock_opportunities']} | {m['training_completed']} | NOT_FIT |")
    text += ["", "## سبب الرفض", "",
        "المدخل `log1p_large_bar_age` يمثل العمر منذ آخر شمعة M5 نطاقها أكبر من3×ATR السابق. يجب أن يبقى مجهولًا قبل أول حدث أو بعد فجوة. بعد إزالة الانفجارات، لم تحدث شمعة تستوفي هذا التعريف في أي إعداد من الثمانية؛ لذلك بقي هذا المدخل مجهولًا في جميع الصفوف. تتطلب صيغة44 الأصلية أن تكون كل مدخلاتها finite، فتوقف التوافر المشترك بالكامل.", "",
        "لم نعوّض العمر بصفر، ولم نحذف المدخل أو نستبدله أو نعدّل العتبة بعد النتيجة. لم يُدرَّب النموذج الأصلي على عينة مختلفة لإنقاذ المقارنة الزوجية. يوجد شرط>=1000 نتيجة تدريب مشتركة مكتملة؛ العدد المرصود صفر. ذلك يرفض قابلية تطبيق هذا التمثيل كما حُدد، ولا يثبت أن كل طرق إزالة أثر الانفجارات خاسرة.", "",
        "## إعادة البناء المستقلة", "",
        "أعاد مدقق مستقل قراءة كل الأسعار عبر NumPy دون استيراد أي محرك بحث. أعاد حساب وسيط التدريب، والسلسلة المحوّلة بتجميع متجه مستقل، وكل إغلاقات M5 وعلامات الشموع الكبيرة وأعمارها، والتوافر وعضوية التدريب وحالات عدم التدريب. طابق كل الخلايا الـ72 الفارغة والمخرجات دون اختراع صفقات أو PF أو فواصل عائد.", "",
        f"التدقيق: **{audit['checks']:,} فحصًا، صفر أخطاء**. الحساب الفعلي لـlongdouble على هذه البيئة له{audit['oracle_longdouble_mantissa_bits']} بتًا للكسر؛ لا ندعي دقة أعلى منfloat64 هنا. المقارنة العددية المعلنة في المدقق2e-9 نسبيًا؛ لم تُعدّل بعد الفحص. فحص Boom الأول المستقل نجح أيضًا، وسجله محفوظ.", "",
        "| الرمز | الإعداد | تغيّرات كبيرة أزيلت | شموع M5 كبيرة بعد التحويل | صفوف بعمر معلوم | صفوف بكل44 مدخلًا finite |",
        "|---|---|---:|---:|---:|---:|"]
    for symbol in ("BOOM600", "CRASH600"):
        for fold in ("fit40", "fit50", "fit60", "fit70"):
            x = audit["symbols"][symbol][fold]
            text.append(f"| {symbol} | {fold} | {x['tail_increments_removed']} | {x['large_transformed_m5_bars']} | {x['known_age_rows']} | {x['all44_finite_rows']} |")
    text += ["", "هذه أعداد وصفية من إعادة بناء فترات متداخلة، وليست أحداثًا أو صفقات مستقلة تُجمع. التدقيق لم يُعد اشتقاق الخصائص الـ43 الأخرى، ولم يختبر حساب معاملات أو أرباح نموذج مدرّب؛ لا يوجد نموذج مدرّب في هذه التجربة.", "",
        "## حدود النتيجة وما يليها", "",
        "نرفض اعتماد هذه النسخة ولا ننقلها إلى توصيات أو تداول. القواعد المجمدة للمناطق كانت0.45–0.55ATR عكس اتجاه الحركة الأصلية، وإبطالًا أبعد0.25ATR، وانتظار15 دقيقة وتفعيلًا بعد دقيقة، ثم دخول السعر الأصلي التالي ووقف2ATR/خروج15 دقيقة وتكلفة افتراضية0.10ATR. لم يصل أي نموذج إلى مرحلة إصدار منطقة فعلية، لذلك أثر هذه المناطق على الربح لم يُختبر اقتصاديًا.", "",
        "أي تصميم يفصل وصف الانفجار الأصلي عن مؤشرات السلسلة المحوّلة سيكون فرضية جديدة وتصريحًا منفصلًا؛ ليس إصلاحًا صامتًا لهذه التجربة ولا نتيجة ربح لها. نتائج مناطق CRT/Fibonacci/Trend السابقة لا تتغير، وأقرب PF سابق يبقى Crash Trend1.477 من60 صفقة غير متأهلة. هدف المستخدم ما زال نشطًا وغير متحقق.", "",
        "اختبارات ما قبل القياس173passed؛ الاختبارات الكاملة2462passed وتحذير Starlette/httpx موجود مسبقًا. اختبارات المدقق المستقل8passed، والترجمة البرمجية نجحت. فشل أولي في ستة fixtures بسبب تمرير ثلاثة معاملات لمنشئ الكاشف ذي المعاملين محفوظ؛ أُصلحت fixtures قبل القياس، وليس قاعدة السوق أو العتبة.", "",
        "LIVE_TRADING=false، READY_FOR_LIVE=false، LIVE_ALLOWED=false، OPENED_TRADES=false. تنفيذCFD والتكاليف الفعلية والأرباح النقدية والتجربة الورقية الاستباقية: NOT TESTED.", "",
        "## الملفات", "",
        "- [البروتوكول المجمد](PROTOCOL.md)، [التصريح وSHA](declaration.json)، [كل72 خلية](results.json).",
        "- [التدقيق المستقل](independent_availability_audit.json)، [الفحص الأول](independent_precheck.json).",
        "- ملفات *_availability.csv.gz و*_model.json و*_training_labels.csv.gz تحفظ التوافر وحالات عدم التدريب. ملفات الإشارات والمناطق والصفقات الفارغة محفوظة أيضًا.",
        "- ملفات الخصائص الكاملة محلية تحتdata/representation_regions_20261008، وبصماتها فيresults.json والتدقيق. لا تكفي ملفات Git وحدها دون بيانات الأسعار المحلية لإعادة الحساب.",
        "- [نتائج المناطق السابقة](../zone_study_20261008/REPORT.ar.md)، [تعريفات الحركة الاثنا عشر](../zone_excursions_20261008/REPORT.ar.md).", ""]
    with (OUT / "REPORT.ar.md").open("x") as f: f.write("\n".join(text))
    print(json.dumps({"report": str((OUT / "REPORT.ar.md").relative_to(ROOT)), "checks": audit["checks"], "models_fitted": 0}))


if __name__ == "__main__": main()
